private List<Integer> mergeBounds(List<Integer> leftBounds, List<Integer> rightBounds,
                                 int start, int end) {
    List<Integer> result = new ArrayList<>();
    int left = start;
    int right = end - 1;
    while (left < end && right >= 0) {
        if (leftBounds.get(left) < rightBounds.get(right)) {
            result.add(leftBounds.get(left));
            left++;
        } else {
            result.add(rightBounds.get(right));
            right--;
        }
    }
    if (left < end) {
        result.addAll(leftBounds.subList(left, end));
    } else if (right >= 0) {
        result.addAll(rightBounds.subList(0, right + 1));
    }
    return result;
}

