    if (this.isVirtual || this.next.isVirtual) {
        // If either node is virtual, get its real counterpart
        Node realThis = this.isVirtual ? this.getRealNode() : this;
        Node realNext = this.next.isVirtual ? this.next.getRealNode() : this.next;

        // Create the edge between the real nodes
        Edge edge = new Edge(realThis, realNext);

        return edge;
    } else {
        // Both nodes are real, so create the edge between them
        Edge edge = new Edge(this, this.next);

        return edge;
    }
}

