public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    if (file == null || timeRanges == null) {
        throw new IllegalArgumentException("File or time ranges cannot be null");
    }

    // create a new CSV parser for the file
    CSVParser parser = new CSVParser(new FileReader(file));

    // create a new list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    for (CSVRecord record : parser) {
        // get the timestamp for the current record
        long timestamp = Long.parseLong(record.get(0));

        // check if the timestamp is within any of the specified time ranges
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (timeRange.contains(timestamp)) {
                // create a new thread snapshot from the current record
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(record);
                // add the thread snapshot to the list
                threadSnapshots.add(threadSnapshot);
                break;
            }
        }
    }

    // close the parser
    parser.close();

